alter table public.channel_integrations add constraint channel_integrations_channel_check CHECK ((channel = ANY (ARRAY['swiggy'::text, 'zomato'::text, 'ondc'::text, 'website'::text, 'whatsapp'::text, 'qr'::text])));
alter table public.kot_tickets add constraint kot_tickets_priority_check CHECK ((priority = ANY (ARRAY['normal'::text, 'urgent'::text])));
alter table public.kot_tickets add constraint kot_tickets_status_check CHECK ((status = ANY (ARRAY['new'::text, 'preparing'::text, 'ready'::text, 'delivered'::text])));
alter table public.menu_categories add constraint menu_categories_name_not_blank CHECK ((length(btrim(name)) > 0));
alter table public.menu_items add constraint menu_items_course_check CHECK ((course = ANY (ARRAY['eat'::text, 'drink'::text])));
alter table public.menu_items add constraint menu_items_food_type_check CHECK ((food_type = ANY (ARRAY['veg'::text, 'non_veg'::text, 'egg'::text])));
alter table public.menu_items add constraint menu_items_name_not_blank CHECK ((length(btrim(name)) > 0));
alter table public.menu_items add constraint menu_items_price_non_negative CHECK ((price >= (0)::numeric));
alter table public.order_items add constraint order_items_qty_check CHECK ((qty > 0));
alter table public.order_items add constraint order_items_status_check CHECK ((status = ANY (ARRAY['pending'::text, 'preparing'::text, 'ready'::text, 'delivered'::text, 'cancelled'::text])));
alter table public.order_items add constraint order_items_unit_price_check CHECK ((unit_price >= (0)::numeric));
alter table public.orders add constraint orders_channel_check CHECK ((channel = ANY (ARRAY['dine_in'::text, 'delivery'::text, 'pickup'::text, 'online'::text, 'swiggy'::text, 'zomato'::text, 'other'::text])));
alter table public.orders add constraint orders_payment_method_check CHECK (((payment_method IS NULL) OR (payment_method = ANY (ARRAY['cash'::text, 'upi'::text, 'card'::text, 'split'::text]))));
alter table public.orders add constraint orders_placed_by_check CHECK ((placed_by = ANY (ARRAY['pos'::text, 'captain'::text, 'guest'::text, 'integration'::text])));
alter table public.orders add constraint orders_status_check CHECK ((status = ANY (ARRAY['new'::text, 'in_billing'::text, 'sent_to_kitchen'::text, 'ready'::text, 'awaiting_payment'::text, 'paid'::text, 'delivered'::text, 'cancelled'::text])));
alter table public.organizations add constraint organizations_contact_email_format CHECK (((contact_email IS NULL) OR (contact_email ~ '^[^@[:space:]]+@[^@[:space:]]+\.[^@[:space:]]+$'::text)));
alter table public.organizations add constraint organizations_gstin_format CHECK (((gstin IS NULL) OR (gstin ~ '^[0-9]{2}[A-Z]{5}[0-9]{4}[A-Z][0-9A-Z][Z][0-9A-Z]$'::text)));
alter table public.organizations add constraint organizations_name_not_blank CHECK ((length(btrim(name)) > 0));
alter table public.organizations add constraint organizations_slug_format CHECK (((slug ~ '^[a-z0-9]+(-[a-z0-9]+)*$'::text) AND ((length(slug) >= 2) AND (length(slug) <= 63))));
alter table public.organizations add constraint organizations_theme_shape CHECK (((jsonb_typeof(theme) = 'object'::text) AND ((NOT (theme ? 'accent'::text)) OR ((theme ->> 'accent'::text) ~ '^#[0-9a-fA-F]{6}$'::text)) AND ((NOT (theme ? 'backgroundOpacity'::text)) OR ((jsonb_typeof((theme -> 'backgroundOpacity'::text)) = 'number'::text) AND ((((theme ->> 'backgroundOpacity'::text))::numeric >= (0)::numeric) AND (((theme ->> 'backgroundOpacity'::text))::numeric <= (1)::numeric))))));
alter table public.payments add constraint payments_amount_check CHECK ((amount > (0)::numeric));
alter table public.payments add constraint payments_method_check CHECK ((method = ANY (ARRAY['cash'::text, 'upi'::text, 'card'::text, 'wallet'::text, 'due'::text, 'other'::text])));
alter table public.roles add constraint roles_slug_format CHECK ((slug ~ '^[a-z0-9]+(_[a-z0-9]+)*$'::text));
